CREATE TABLE IF NOT EXISTS asterisk_ownership (id TINYINT NOT NULL PRIMARY KEY, tenant_id VARCHAR(128) NOT NULL, pbx_id VARCHAR(128) NOT NULL, version INT NOT NULL);
CREATE TABLE IF NOT EXISTS pjsip_registration_events (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, event_time DATETIME(3) NOT NULL, endpoint VARCHAR(64) NOT NULL, aor VARCHAR(64) NOT NULL DEFAULT '', contact_uri VARCHAR(255) NOT NULL DEFAULT '', status VARCHAR(16) NOT NULL, user_agent VARCHAR(255) NOT NULL DEFAULT '', via_address VARCHAR(64) NOT NULL DEFAULT '', reg_expire DATETIME(3) NULL, rtt_usec BIGINT NOT NULL DEFAULT 0, KEY idx_endpoint_time(endpoint,event_time), KEY idx_time(event_time));
CREATE TABLE IF NOT EXISTS asterisk_observation_gaps (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, started_at DATETIME(3) NOT NULL, ended_at DATETIME(3) NULL, KEY idx_gap_time(started_at));
